import java.util.Scanner; import java.util.Arrays; public class TestClass { public static void main(String[] args) throws Exception { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int t = sc.nextInt(); while (t-- > 0) { int n = sc.nextInt(); int m = sc.nextInt(); int[] arr = new int[n]; for (int i = 0; i < n; i++) { arr[i] = sc.nextInt(); } Arrays.sort(arr); long minSum = 0; long maxSum = 0; int k = n - m; for (int i = 0; i < k; i++) { minSum += arr[i]; } for (int i = n - 1; i >= n - k; i--) { maxSum += arr[i]; } System.out.println(maxSum - minSum); } sc.close(); } }